function longestDiagonalArea(rects: number[][]): number {
  let bestDiag = 0, bestArea = 0;
  for (const [l, w] of rects) {
    const d = l * l + w * w, a = l * w;
    if (d > bestDiag) {
      bestDiag = d;
      bestArea = a;
    } else if (d === bestDiag && a > bestArea) {
      bestArea = a;
    }
  }
  return bestArea;
}

