    def longestDiagonalArea(self, rects: List[List[int]]) -> int:
        best_diag = best_area = 0
        for l, w in rects:
            d, a = l * l + w * w, l * w
            if d > best_diag:
                best_diag, best_area = d, a
            elif d == best_diag:
                best_area = max(best_area, a)
        return best_area

